/**
 * @distilled.cloud/whatsapp -- WhatsApp Business Platform SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` converts from Meta's OpenAPI spec
 * (https://github.com/facebook/openapi), mirrored at
 * `specs/spec-mirror-whatsapp/specs/openapi.yaml`. Everything else in this
 * folder is hand-written.
 *
 * @example
 * ```ts
 * import * as Effect from "effect/Effect";
 * import * as Layer from "effect/Layer";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as WhatsApp from "@distilled.cloud/whatsapp";
 *
 * const program = WhatsApp.getPhoneNumber({ Phone_Number_ID: "106540352242922" });
 *
 * program.pipe(
 *   Effect.provide(
 *     Layer.mergeAll(FetchHttpClient.layer, WhatsApp.CredentialsFromEnv, WhatsApp.WhatsAppProtocol),
 *   ),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { WhatsAppProtocol, type WhatsAppOpError, type WhatsAppOpContext } from "./protocol.ts";
export { paginateGraph } from "./pagination.ts";
export * as Retry from "./retry.ts";
// Operations, their request/response types, their typed errors and the
// `WebhookPayload` type are importable straight off the package root; the
// errors every operation can answer come from ./errors.ts. The generated
// status classes shadow the same-named core ones from ./errors.ts -- the
// operations raise the generated classes (same `_tag`).
export * from "./services/whatsapp.ts";
export {
  BadRequest,
  Conflict,
  Forbidden,
  NotFound,
  UnprocessableEntity,
} from "./services/whatsapp.ts";
